/// Installs the production Timeline/Animation composition subset into an Editor preview world.
///
/// This deliberately reuses the same Timeline, Animation, Transform, pose-composition, and
/// optional secondary-motion systems as packaged playback while omitting gameplay input,
/// character motors, collision, combat, navigation, and ordinary audio autoplay. The Scene View
/// therefore samples Timeline state without becoming a second simplified evaluator or advancing
/// unrelated gameplay simulation.
pub fn register_timeline_preview_systems(
    app: &mut App,
    graph_enabled: bool,
    secondary_physics_enabled: bool,
) {
    if app
        .world()
        .get_resource::<Assets<AnimationClip>>()
        .is_none()
    {
        app.insert_resource(Assets::<AnimationClip>::default());
    }
    if app.world().get_resource::<AnimationEvents>().is_none() {
        app.insert_resource(AnimationEvents::default());
    }
    if app.world().get_resource::<PoseArena>().is_none() {
        app.insert_resource(PoseArena::new());
    }
    if app.world().get_resource::<SecondaryMotionWorlds>().is_none() {
        app.insert_resource(SecondaryMotionWorlds::default());
    }
    if app.world().get_resource::<SpatialAudioRuntime>().is_none() {
        app.insert_resource(SpatialAudioRuntime::default());
    }
    if app.world().get_resource::<TimelineRuntime>().is_none() {
        app.insert_resource(TimelineRuntime::default());
    }
    if app.world().get_resource::<TimelineEvents>().is_none() {
        app.insert_resource(TimelineEvents::default());
    }
    if app
        .world()
        .get_resource::<GameCameraSelectionOverride>()
        .is_none()
    {
        app.insert_resource(GameCameraSelectionOverride::default());
    }

    app.add_fixed_system(rig_pose_clear_transient_system);
    if graph_enabled {
        app.add_fixed_system(anim_graph_system);
    }
    app.add_fixed_system(timeline_prepare_system);
    app.add_fixed_system(animation_system);
    app.add_fixed_system(timeline_transform_system);
    app.add_fixed_system(transform_propagation_system);
    app.add_fixed_system(foot_ik_system);
    if secondary_physics_enabled {
        app.add_fixed_system(secondary_motion_system);
    }
    app.add_fixed_system(publish_final_rig_pose_system);
    app.add_fixed_system(transform_propagation_system);
}

